<template>
  <div class="space-y-6">
    <div class="flex items-center justify-between">
      <h2 class="text-xl font-bold text-ink-gray-9">Jobs</h2>
      <div class="flex gap-2">
        <Button variant="subtle" @click="jobs.reload()" :loading="jobs.loading">
          Refresh
        </Button>
      </div>
    </div>

    <div class="rounded-lg border bg-surface-white shadow-sm ring-1 ring-outline-gray-2 overflow-hidden">
      <JobTable :jobs="jobs.data || []" :loading="jobs.loading" @viewLogs="handleViewLogs" />
    </div>

    <Dialog
      v-if="selectedJob"
      v-model="showLogModal"
      :title="`Job Logs: ${selectedJob.name}`"
      size="xl"
    >
      <template #body>
        <pre class="rounded-lg bg-ink-gray-9 p-4 font-mono text-xs text-surface-white h-96 overflow-y-auto">{{ selectedJob.logs || 'No logs for this job.' }}</pre>
      </template>
    </Dialog>
  </div>
</template>

<script setup>
import JobTable from "@/components/jobs/JobTable.vue"
import { createResource } from "frappe-ui"
import { ref } from "vue"

const showLogModal = ref(false)
const selectedJob = ref(null)

const jobs = createResource({
	url: "htbencher.api.get_jobs",
	auto: true,
})

function handleViewLogs(job) {
	selectedJob.value = job
	showLogModal.value = true
}
</script>
